/**
 * `amplify_outputs.json` is generated by `npx ampx sandbox` (or by Amplify
 * Hosting at build time) and is gitignored, so it does not exist in a fresh
 * clone. Declaring it keeps `tsc` and `npm run build` working before the
 * backend has been provisioned; the import site already handles it being
 * absent at runtime.
 */
declare module '*/amplify_outputs.json' {
  // Shape is validated by Amplify.configure at runtime, not here.
  const outputs: any;
  export default outputs;
}
